; Runtime library routines

; u16Div — unsigned 16-bit divide
; Input:  $B0,$B1 = dividend (u16), $B2,$B3 = divisor (u16)
; Output: $B0,$B1 = quotient (u16), $B2,$B3 = remainder (u16)

u16Div:
    LDA #$00
    STA $B4         ; remainder lo
    STA $B5         ; remainder hi
    LDX #16
.loop:
    ASL $B0
    ROL $B1         ; shift dividend left
    ROL $B4
    ROL $B5         ; shift into remainder
    ; Compare remainder with divisor
    LDA $B4
    CMP $B2
    LDA $B5
    SBC $B3
    BCC .no_sub
    ; remainder >= divisor: subtract
    LDA $B4
    SEC
    SBC $B2
    STA $B4
    LDA $B5
    SBC $B3
    STA $B5
    INC $B0         ; set quotient bit
.no_sub:
    DEX
    BNE .loop
    LDA $B4 : STA $B2
    LDA $B5 : STA $B3
    RTS


; u16Mod — unsigned 16-bit modulus
; Input:  $B0,$B1 = dividend (u16), $B2,$B3 = divisor (u16)
; Output: $B0,$B1 = remainder (u16)

u16Mod:
    JSR u16Div
    LDA $B2 : STA $B0
    LDA $B3 : STA $B1
    RTS


; u16Mul — unsigned 16-bit multiply
; Input:  $B0,$B1 = operand1 (u16 little-endian)
;         $B2,$B3 = operand2 (u16 little-endian)
; Output: $B0,$B1,$B2,$B3 = result (u32 little-endian)
;
; Method: shift-and-add (16x16 -> 32)

u16Mul:
    ; result in $B4-$B7, then copy to $B0-$B3
    LDA #$00
    STA $B4
    STA $B5
    STA $B6
    STA $B7
    LDX #16         ; 16 bits
.loop:
    LSR $B3
    ROR $B2         ; shift multiplier right
    BCC .no_add
    CLC
    LDA $B4
    ADC $B0
    STA $B4
    LDA $B5
    ADC $B1
    STA $B5
    LDA $B6
    ADC #$00
    STA $B6
    LDA $B7
    ADC #$00
    STA $B7
.no_add:
    ASL $B0
    ROL $B1         ; shift multiplicand left
    DEX
    BNE .loop
    ; Copy result
    LDA $B4 : STA $B0
    LDA $B5 : STA $B1
    LDA $B6 : STA $B2
    LDA $B7 : STA $B3
    RTS


; _heap_alloc: allocate A bytes from heap (grows downward)
;   Entry: A = byte count
;   Exit:  A/X = pointer to allocated area (lo/hi)
;   Decrements HP by A, zero-fills the area, returns new HP.
_heap_alloc:
    STA $84
    SEC
    LDA $86
    SBC $84
    STA $86
    LDA $87
    SBC #$00
    STA $87
    LDY $84
    BEQ _ha_done
    LDA #$00
_ha_zero:
    DEY
    STA ($86),Y
    CPY #$00
    BNE _ha_zero
_ha_done:
    LDA $86
    LDX $87
    RTS

